  JSON.stringify(semanticQueue(baseline)) === JSON.stringify(semanticQueue(reversed)) &&
  JSON.stringify(baseline.counts) === JSON.stringify(reversed.counts));
check('invalid_batch_shape_is_rejected_with_empty_outputs',
  invalidBatch.batch_status === 'rejected' && invalidBatch.input_count === 0 &&
