check('scope_flags_do_not_claim_approval_persistence_or_external_work',
  cases.every(result => result.scope?.input === 'synthetic_structured_exports' &&
    result.scope?.duplicate_handling === 'this_batch_only' &&
    result.scope?.durable_cross_run_idempotency === false &&
    result.scope?.human_approval_performed === false &&
